/* @autogenerated */
import { ChangeDetectionStrategy, Component, computed, inject } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialogModule, MatDialogRef } from '@angular/material/dialog';
import { RouterLink } from '@angular/router';
import { MatButtonModule } from '@angular/material/button';
import { TranslocoPipe } from '@jsverse/transloco';
import { AppStateService } from '@shared/context/state/app-state.service';
import { describeError, ErrorPageComponent } from '../error-page/error-page.component';

export interface ErrorModalData {
  error: any;
  /** Solo en los 401 que se resuelven iniciando sesión (`ErrorService.loginAction`). */
  login?: () => void;
}

@Component({
  selector: 'error-modal',
  standalone: true,
  imports: [MatDialogModule, MatButtonModule, RouterLink, TranslocoPipe, ErrorPageComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './error-modal.component.html',
})
export class ErrorModalComponent {
  private readonly dialogRef = inject<MatDialogRef<ErrorModalComponent>>(MatDialogRef);
  private readonly state = inject(AppStateService);
  readonly data = inject<ErrorModalData>(MAT_DIALOG_DATA);

  /** El título de la página de error pasa a ser el del diálogo. */
  readonly title = 'errors.page.' + describeError(this.data.error).kind + '.title';
  /** El enlace de la página de error no cierra el diálogo: se pinta aquí, junto a las demás acciones. */
  readonly home = computed(() => ['/', this.state.language(), this.state.tenant()]);

  /** Cierra el aviso e inicia sesión; la ruta actual ya está guardada para volver a ella tras el login. */
  public login() {
    this.dialogRef.close();
    this.data.login?.();
  }
}
